mapper.select:
/* DailyJoinMapper.selectUserIdDupleCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_USER
     WHERE CMPNY_CD = #{cmpnyCd}
       AND USER_ID  = #{userId}
       AND USE_YN   = 'Y'
     LIMIT 1
) T

/* DailyJoinMapper.selectMblNoDupleCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_USER
     WHERE CMPNY_CD    = #{cmpnyCd}
       AND MBL_NO_HMAC = #{mblNoHmac}
       AND USE_YN      = 'Y'
     LIMIT 1
) T

/* DailyJoinMapper.selectSmsVerifiedSmsId */
SELECT SMS_ID
  FROM TB_SMS_AUTH_CODE
 WHERE MBL_NO_HMAC = #{mblNoHmac}
   AND AUTH_CD     = #{certNo}
   AND VERIFIED_YN = 'Y'
   AND UPDATE_DATE  >=  DATE_SUB(NOW(), INTERVAL 10 MINUTE)
 ORDER BY UPDATE_DATE DESC
 LIMIT 1

/* DailyJoinMapper.selectLinkPolicyUseYn */
SELECT USE_YN
FROM TB_DAILY_USER_LINK_POLICY
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}

/* DailyJoinMapper.selectFirstEmptySlotNo */
SELECT SLOT_NO
FROM TB_DAILY_USER_SLOT
WHERE CMPNY_CD    = #{cmpnyCd}
  AND SITE_CD     = #{siteCd}
  AND USE_YN      = 'Y'
  AND SLOT_STATUS = '00'
  AND (CURR_USER_CD IS NULL OR CURR_USER_CD = '')
ORDER BY CAST(SLOT_NO AS UNSIGNED)
LIMIT 1

/* DailyJoinMapper.selectDailyUserCd */
SELECT CONCAT('D', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_USER'))
FROM DUAL

mapper.insert:
/* DailyJoinMapper.insertDailyUser */
INSERT INTO TB_DAILY_USER (
    CMPNY_CD
    , SITE_CD
    , USER_CD
    , USER_ID
    , USER_NM
    , USER_PW

    , MBL_NO_ENC
    , MBL_NO_HMAC
    , MBL_NO_LAST4

    , REG_TYPE
    , USE_YN
    , ACCOUNT_STATUS
    , WORK_EXPIRE_DATE

    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
    #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{userId}
    , #{userNm}
    , #{userPw}

    , #{mblNoEnc}
    , #{mblNoHmac}
    , #{mblNoLast4}

    , #{regType}
    , #{useYn}
    , #{accountStatus}
    , DATE_FORMAT(NOW(), '%Y%m%d')

    , #{userCd}
    , NOW()
    , #{userCd}
    , NOW()
)

mapper.update:
/* DailyJoinMapper.updateDailyUserSlotCurrUserCd */
UPDATE TB_DAILY_USER_SLOT
SET CURR_USER_CD = #{userCd}
    , SLOT_TYPE   = #{slotType}
    , SLOT_STATUS = #{slotStatus}
    , UPDATE_NO   = #{userCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD    = #{cmpnyCd}
  AND SITE_CD     = #{siteCd}
  AND SLOT_NO     = #{slotNo}
  AND USE_YN      = 'Y'
  AND SLOT_STATUS = '00'
  AND (CURR_USER_CD IS NULL OR CURR_USER_CD = '')

