INSERT INTO TB_TERMS_USER_AGR_MGMT (
    USER_CD
    , TERMS_ID
    , TERMS_VERSION
    , AGR_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{userCd}
    , #{termsId}
    , #{termsVersion}
    , #{agrYn}
    , #{userCd}
    , NOW()
)
